{
  "case_id": "xsu_sg_009_medical_documentation_content",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Kernen er korrekt (varig funktionsnedsættelse, journaler, udrednings-/behandlingsforløb, aktuelle symptomer, aktuel og fyldestgørende dokumentation). Men svaret nævner ikke diagnose (hvis stillet), planlagt behandling eller erhvervsevne. Det fremstiller også \"aktuelle symptomer\" som vejledningens indhold, hvilket ikke står i 4.2. Desuden henviser det til et lovforslag (L 152) som en slags kilde og siger, at en diagnose alene \"ikke er nok\" med støtte i forarbejder, ikke i vejledningen. Samlet er svaret ikke fuldt i overensstemmelse med rubrikken."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Mangler flere kritiske elementer: eksplicit diagnose (hvis stillet), planlagt behandling (kun \"eventuelt er planlagt\" i tommelfingerreglen, men ikke som element fra vejledningen), påvirkning af erhvervsevnen (hvis muligt) og at oplysningerne skal fremsendes, når de er tilgængelige i journalen. Art og grad nævnes ikke eksplicit."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret handler direkte om, hvad den lægelige dokumentation skal beskrive. Det rummer en del overflødig tekst om forarbejder, men besvarer spørgsmålet."
    },
    "c04_source_traceability": {
      "label": "met",
      "reason": "Svaret angiver identificerbare kilder: vejledning nr. 10157, SU-bekendtgørelsen og lovforslag L 152. Udsagnene er knyttet til dem med henvisninger."
    },
    "c05_source_validity": {
      "label": "not_met",
      "reason": "Vejledningen og SU-bekendtgørelsen er gyldige og aktuelle. L 152 (2024-25) er et lovforslag/forarbejde, der ikke indgår i den frosne kildeafgrænsning, og svaret erkender selv, at det ikke er gældende hjemmel. Det bruges alligevel som støtte for et materielt udsagn."
    },
    "c06_claim_source_support": {
      "label": "not_met",
      "reason": "Påstanden om, at diagnose alene eller medicinkort ikke er tilstrækkeligt, støttes af forarbejderne, ikke af de frosne kilder. Den lægger sig heller ikke op ad vejledningen, der kun siger \"diagnose (hvis stillet)\" som del af en fyldestgørende dokumentation. \"Aktuelle symptomer og udfordringer\" og \"medfødt funktionsnedsættelse: sygehistorik\" findes ikke i afsnit 4.2 og er kun støttet af uafklarede henvisninger. Der er ingen støtte for, at dokumentation for alle funktionsnedsættelser skal medsendes samt oplysning om, at der søges på flere forhold."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer krav om medfødte funktionsnedsættelser (sygehistorik og seneste journalnotater) og flere funktionsnedsættelser (oplysning om, at der søges på flere forhold). Disse indgår ikke i de udleverede kilder. Det tilføjer også udsagnet om diagnose alene og medicinkort fra forarbejder uden for kildeafgrænsningen."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Forbeholdene \"hvis diagnose er stillet\", \"hvis behandling er planlagt\", \"hvis erhvervsevnen kan beskrives\" og tilgængelighed i journalen bevares ikke. Svaret nævner kun \"hvis relevant\" for flere funktionsnedsættelser."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er internt sammenhængende, og konklusionen følger af de anførte trin. Det skelner endda mellem forarbejder og gældende hjemmel."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Svaret skriver, at dokumentationen \"bør\" beskrive forhold, som vejledningen formulerer som \"skal\" (udrednings- og behandlingsforløb). Samtidig gør det oplysninger fra vejledningens liste til noget blot \"helst\" ønskeligt (\"praktisk tommelfingerregel\"), og det mister kravet om at fremsende tilgængelige oplysninger. \"Det er ikke nok\" fremstilles som en regel, selvom den hviler på forarbejder."
    }
  },
  "xhaile_coverage": {
    "A39": {
      "label": "no",
      "reason": "Diagnose (hvis stillet) nævnes ikke som element i dokumentationen. Svaret omtaler kun, at en rent diagnose ikke er nok."
    },
    "A41": {
      "label": "yes",
      "reason": "Svaret nævner udrednings- og behandlingsforløb samt forløb, og i tommelfingerreglen sygdomsforløb og konsekvenser. Det dækker i det væsentlige sygdomsforløbet."
    },
    "A42": {
      "label": "yes",
      "reason": "Behandlingsforløb er eksplicit nævnt (udredningsforløb og behandlingsforløb)."
    },
    "A45": {
      "label": "partial",
      "reason": "Svaret nævner kun \"hvilken behandling/udredning der har været og eventuelt er planlagt\" i tommelfingerreglen. Det hviler på tvivlsom støtte og beskriver ikke planlagt behandling som selvstændigt element."
    },
    "A47": {
      "label": "no",
      "reason": "Påvirkning af erhvervsevnen (hvis muligt) nævnes ikke. Svaret taler kun om daglig funktionsevne."
    }
  },
  "overall_notes": "Svaret rammer kernen (varig funktionsnedsættelse, journaler, udrednings- og behandlingsforløb, aktuel dokumentation), men udelader diagnose, erhvervsevne og tilgængelighedsforbeholdet. Det tilføjer elementer uden støtte i de frosne kilder og læner sig op ad et lovforslag. Modalitet er blødt op til \"bør\"/\"helst\"."
}

